using System.Text.Json;
using System.Text.Json.Nodes;
using Erp.CodeGen.Design;

namespace Erp.CodeGen.Emit;

/// <summary>
/// Settings manifests (slice S1.09a build item 1): each module's checked <c>Settings/settings.yaml</c> becomes
/// <c>Access/settings.g.json</c>, which <c>migrate</c> and provisioning register (the migrator already ships the Access
/// folder), and a constants class of its keys in the module's Contracts project.
/// </summary>
public static class SettingsEmitter
{
    private const string Header =
        "// <auto-generated>\n" +
        "// Generated by tools/Erp.CodeGen from the module's Settings/settings.yaml (slice S1.09a). Do not edit by hand.\n" +
        "// </auto-generated>\n" +
        "#nullable enable\n\n";

    public static void Emit(IReadOnlyList<ModuleSettingsManifest> manifests, OutputSet output)
    {
        ArgumentNullException.ThrowIfNull(manifests);
        ArgumentNullException.ThrowIfNull(output);
        foreach (var m in manifests)
        {
            output.Add($"{m.Folder}/Access/settings.g.json", Json(m));
            var project = m.Module == "hrm" ? "Hrm" : "Kernel";
            var contracts = m.Module == "hrm" ? "src/Modules/Hrm/Erp.Hrm.Contracts" : "src/Platform/Erp.Kernel.Contracts";
            output.Add($"{contracts}/Generated/{project}SettingKeys.g.cs", Keys(m, project));
        }
    }

    private static string Json(ModuleSettingsManifest m)
    {
        static JsonObject Texts(IReadOnlyDictionary<string, string> texts) => new() { ["en"] = texts["en"], ["ur"] = texts["ur"] };
        var settings = new JsonArray();
        foreach (var s in m.Settings)
        {
            settings.Add(new JsonObject
            {
                ["key"] = s.Key,
                ["module"] = s.Module,
                ["type"] = s.Type,
                ["default"] = s.Default.DeepClone(),
                ["validation"] = JsonNode.Parse(s.ValidationJson),
                ["layers"] = new JsonArray(s.Layers.Select(l => (JsonNode)JsonValue.Create(l)).ToArray()),
                ["roleRule"] = s.RoleRule,
                ["tightenOnly"] = s.TightenOnly,
                ["selfService"] = s.SelfService,
                ["visible"] = s.Visible,
                ["requiresApproval"] = s.RequiresApproval,
                ["area"] = s.Area,
                ["unit"] = s.Unit,
                ["name"] = Texts(s.Name),
                ["description"] = Texts(s.Description),
                ["help"] = Texts(s.Help),
            });
        }

        var flags = new JsonArray();
        foreach (var f in m.Flags)
        {
            flags.Add(new JsonObject
            {
                ["key"] = f.Key,
                ["module"] = f.Module,
                ["default"] = f.Default,
                ["entitlementKey"] = f.EntitlementKey,
                ["name"] = Texts(f.Name),
                ["description"] = Texts(f.Description),
                ["help"] = Texts(f.Help),
            });
        }

        var root = new JsonObject
        {
            ["_generated"] = $"{OutputSet.Marker} by tools/Erp.CodeGen from {m.Folder}/{SettingsManifestLoader.ManifestPath}; do not edit",
            ["module"] = m.Module,
            ["moduleIds"] = new JsonArray(m.ModuleIds.Select(i => (JsonNode)JsonValue.Create(i)).ToArray()),
            ["settings"] = settings,
            ["flags"] = flags,
        };
        return root.ToJsonString(new JsonSerializerOptions { WriteIndented = true, Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping }) + "\n";
    }

    private static string Keys(ModuleSettingsManifest m, string project)
    {
        var w = new CodeWriter();
        w.Line(Header.TrimEnd('\n')).Line();
        w.Line($"namespace Erp.{project}.Contracts.Generated;").Line();
        w.Line($"/// <summary>Keys of the settings declared in the {m.Module} settings manifest (FR-KRN-SET-01).</summary>");
        w.Open($"public static class {project}SettingKeys");
        foreach (var (s, i) in m.Settings.Select((s, i) => (s, i)))
        {
            if (i > 0)
            {
                w.Line();
            }

            w.Line($"/// <summary>{CodeWriter.Xml(s.Description["en"])}.</summary>");
            w.Line($"public const string {Name(s.Key)} = {CodeWriter.CSharpString(s.Key)};");
        }

        w.Close();
        w.Line();
        w.Line($"/// <summary>Keys of the feature flags declared in the {m.Module} settings manifest (FR-KRN-SET-05).</summary>");
        w.Open($"public static class {project}FlagKeys");
        foreach (var (f, i) in m.Flags.Select((f, i) => (f, i)))
        {
            if (i > 0)
            {
                w.Line();
            }

            w.Line($"/// <summary>{CodeWriter.Xml(f.Description["en"])}.</summary>");
            w.Line($"public const string {Name(f.Key)} = {CodeWriter.CSharpString(f.Key)};");
        }

        w.Close();
        return w.ToString();
    }

    private static string Name(string key) => string.Concat(key.Split('.').Select(Naming.Pascal));
}
